-- ============================================================
-- Norte Aventura — Migración cambios cliente (docx 2026) + pagos
-- Ejecutar en: Supabase Dashboard → SQL Editor (idempotente)
-- ============================================================

-- 1) Tipo de experiencia: clasica | trekking | privada
alter table public.excursions
  add column if not exists tipo text not null default 'clasica'
  check (tipo in ('clasica','trekking','privada'));

update public.excursions set tipo = 'trekking' where slug in (
  'cascada-escondida-san-lorenzo-salta',
  'trekking-andino-llamas-patapampa-tilcara',
  'caravana-de-llamas-centro-de-interpetacion-tilcara',
  'excursion-humahuaca-hornocal-quebrada-de-las-senoritas',
  'cafayate-trekking-y-degustacion'
);

-- 2) Corrección de dificultades (pedido del cliente)
update public.excursions set difficulty = 'Media' where slug in (
  'cascada-escondida-san-lorenzo-salta',
  'trekking-andino-llamas-patapampa-tilcara',
  'excursion-iruya-desde-tilcara'
);

-- 3) Tren Solar: pasa a la lista "Desde Salta" (orden del docx)
update public.excursions
  set category_id = (select id from public.categories where slug = 'salta')
  where slug = 'tren-solar-quebrada-jujuy';

-- 4) Nuevas excursiones del docx (todas "consultar precio")
insert into public.excursions
  (slug, name, location, category_id, tipo, price, price_note, duration, schedule, difficulty, short_desc, description, included, booking_lead, image_url, maps_query, display_order)
values
  ('cerro-elefante-salta','Cerro Elefante','Campo Quijano, Salta',(select id from public.categories where slug='salta'),'trekking',null,'Consultar precio','1 (un) día','Consultar horarios','Media','El cerro con forma de elefante, ícono del Valle de Lerma.','Ascenso guiado al Cerro Elefante, la formación rocosa que vigila el Valle de Lerma junto a la ruta del Tren a las Nubes. Vistas panorámicas del valle, vegetación de transición y una de las postales más buscadas por los senderistas salteños.','Guía, seguro.','Consultar disponibilidad.','https://norteaventura.com.ar/wp-content/uploads/2025/02/20240511_173856-e1745003053876.jpg','Cerro Elefante, Campo Quijano, Salta, Argentina',20),
  ('termas-de-jordan-desde-salta','Termas de Jordán (desde Salta)','San Francisco, Jujuy',(select id from public.categories where slug='salta'),'clasica',null,'Consultar precio','1 (un) día','Consultar horarios','Baja','Aguas termales en plena selva de yungas, saliendo de Salta.','Salida desde Salta hacia las Termas del Jordán, en la selva de yungas jujeñas. Piletones de agua caliente natural rodeados de vegetación y senderos selváticos para relajarse en contacto total con la naturaleza.','Traslado, seguro, guiado.','Consultar disponibilidad.','https://norteaventura.com.ar/wp-content/uploads/2025/04/IMG-20240715-WA0028-e1745460883211.jpg','Termas del Jordán, San Francisco, Jujuy, Argentina',21),
  ('yungas-jujenas','Yungas Jujeñas','Parque Nacional Calilegua, Jujuy',(select id from public.categories where slug='jujuy'),'trekking',null,'Consultar precio','1 (un) día','Consultar horarios','Media','La selva de yungas del Parque Nacional Calilegua.','Inmersión en la selva de yungas del Parque Nacional Calilegua: senderos entre helechos gigantes, avistaje de aves y la biodiversidad más rica del noroeste argentino. Una experiencia verde e intensa, totalmente distinta a la quebrada.','Guía, seguro.','Consultar disponibilidad.','https://norteaventura.com.ar/wp-content/uploads/2025/03/20250105_115140.jpg','Parque Nacional Calilegua, Jujuy, Argentina',22),
  ('cuevas-de-acisibi','Cuevas de Acisibi','Acisibi, Salta',(select id from public.categories where slug='salta'),'trekking',null,'Consultar precio','1 (un) día','Consultar horarios','Media','Cavernas y formaciones ocultas del valle salteño.','Trekking hacia las Cuevas de Acisibi, un sistema de cavernas y formaciones rocosas poco conocidas de los Valles Calchaquíes. Exploración con guía entre galerías naturales, arte rupestre y paisajes de altura.','Guía, seguro.','Consultar disponibilidad.','https://norteaventura.com.ar/wp-content/uploads/2025/02/IMG-20250207-WA0023.jpg','Cuevas de Acisibi, Salta, Argentina',23),
  ('puente-del-diablo-la-poma','Puente del Diablo – La Poma','La Poma, Salta',(select id from public.categories where slug='salta'),'trekking',null,'Consultar precio','1 (un) día','Consultar horarios','Media','El puente natural y los paisajes lunares de La Poma.','Travesía por La Poma hasta el Puente del Diablo, un arco natural de roca sobre el río. Paisajes de badlands, formaciones multicolor y un rincón del noroeste que todavía se siente inexplorado.','Guía, seguro.','Consultar disponibilidad.','https://norteaventura.com.ar/wp-content/uploads/2025/03/20250126_174817-e1772563249896.jpg','La Poma, Salta, Argentina',24),
  ('iruya-trekking-2-dias','Iruya Trekking (2 días)','Iruya, Salta',(select id from public.categories where slug='salta'),'trekking',null,'Consultar precio','2 (dos) días','Consultar horarios','Alta','Dos días de trekking hacia el pueblo colgado de la montaña.','Expedición de dos días hacia Iruya a pie, cruzando abra y quebrada por senderos ancestrales. Noche en el pueblo, contacto con las comunidades y la experiencia de llegar caminando a uno de los lugares más mágicos del norte.','Guía, seguro, logística de apoyo.','Consultar disponibilidad.','https://norteaventura.com.ar/wp-content/uploads/2025/03/IMG-20250115-WA0075-e1772563433316.jpg','Iruya, Salta, Argentina',25),
  ('castillos-de-huichaira-tilcara','Castillos de Huichaira','Tilcara, Jujuy',(select id from public.categories where slug='jujuy'),'clasica',null,'Consultar precio','1/2 (medio) día','Consultar horarios','Media','Torres y espinas rojizas sobre la Quebrada de Huichaira.','Caminata por la Quebrada de Huichaira hasta los Castillos: agujas y formaciones rojizas que emergen del cauce, con vistas amplias de la Quebrada de Humahuaca. Un secreto local a minutos de Tilcara.','Guía, seguro.','Consultar disponibilidad.','https://norteaventura.com.ar/wp-content/uploads/2025/02/IMG-20250207-WA0023.jpg','Quebrada de Huichaira, Tilcara, Jujuy, Argentina',26),
  ('traslado-aeropuerto-jujuy-tilcara','Traslado Aeropuerto Jujuy / Tilcara','Aeropuerto de Jujuy → Tilcara',(select id from public.categories where slug='jujuy'),'privada',null,'Consultar precio','A coordinar','A coordinar','Baja','Transfer privado entre el aeropuerto de Jujuy y Tilcara.','Traslado privado entre el Aeropuerto Gobernador Horacio Guzmán y Tilcara (u otros puntos de la Quebrada). Coordinación previa por WhatsApp, vehículo cómodo y chofer local.','Traslado privado.','Coordinar con anticipación por WhatsApp.','https://norteaventura.com.ar/wp-content/uploads/2025/02/20220304_172731-scaled.jpg','Aeropuerto Internacional Gobernador Horacio Guzmán, Jujuy, Argentina',27),
  ('garganta-del-diablo-tilcara','Garganta del Diablo','Tilcara, Jujuy',(select id from public.categories where slug='jujuy'),'trekking',null,'Consultar precio','1/2 (medio) día','Consultar horarios','Media','El clásico trekking de Tilcara hacia la cascada escondida.','El trekking más emblemático de Tilcara: sendero con vistas a la Quebrada que termina en la Garganta del Diablo, una cascada entre paredones de roca. Ideal como primera caminata en la zona.','Guía, seguro.','Consultar disponibilidad.','https://norteaventura.com.ar/wp-content/uploads/2025/03/20250105_115140.jpg','Garganta del Diablo, Tilcara, Jujuy, Argentina',28),
  ('city-tour-pucara-tilcara','City Tour + Pucará (Tilcara)','Tilcara, Jujuy',(select id from public.categories where slug='jujuy'),'clasica',null,'Consultar precio','1/2 (medio) día','Consultar horarios','Baja','Lo esencial de Tilcara y su fortaleza prehispánica.','Recorrido por el pueblo de Tilcara — plaza, mercado de artesanos, iglesia y museo — con visita guiada al Pucará de Tilcara, la fortaleza omaguaca reconstruida con vista a toda la Quebrada.','Guía, seguro.','Consultar disponibilidad.','https://norteaventura.com.ar/wp-content/uploads/2025/03/IMG-20240503-WA0017.jpg','Pucará de Tilcara, Jujuy, Argentina',29),
  ('salinas-grandes-nocturna','Salinas Grandes — Nocturna','Salinas Grandes, Jujuy',(select id from public.categories where slug='jujuy'),'clasica',null,'Consultar precio','1 (un) día','Consultar horarios','Baja','El salar bajo las estrellas: atardecer y cielo de altura.','Versión nocturna de la visita a Salinas Grandes: llegada al atardecer sobre el mar blanco, fotos doradas y, si el cielo acompaña, una de las noches estrelladas más limpias del país.','Traslado, seguro, guiado.','Consultar disponibilidad.','https://norteaventura.com.ar/wp-content/uploads/2025/04/20220515_153224.jpg','Salinas Grandes, Jujuy, Argentina',30),
  ('termas-de-reyes-lagunas-de-yala','Termas de Reyes + Lagunas de Yala','Termas de Reyes / Yala, Jujuy',(select id from public.categories where slug='jujuy'),'clasica',null,'Consultar precio','1 (un) día','Consultar horarios','Baja','Aguas termales y lagunas de altura cerca de San Salvador.','Jornada de relax entre las Termas de Reyes y las Lagunas de Yala, en el valle jujeño. Baños termales, paisajes serranos y fauna de altura en un mismo día, a poca distancia de San Salvador de Jujuy.','Traslado, seguro, guiado.','Consultar disponibilidad.','https://norteaventura.com.ar/wp-content/uploads/2025/04/IMG-20240715-WA0028-e1745460883211.jpg','Termas de Reyes, Jujuy, Argentina',31),
  ('cuevas-del-wayra','Cuevas del Wayra','Tilcara, Jujuy',(select id from public.categories where slug='jujuy'),'trekking',null,'Consultar precio','1 (un) día','Consultar horarios','Media','Trekking a las cuevas sagradas de la Quebrada.','Trekking de jornada hacia las Cuevas del Wayra, formaciones naturales asociadas a cultos ancestrales de la Quebrada. Paisaje quebradeño, silencio de altura y un objetivo poco masificado.','Guía, seguro.','Consultar disponibilidad.','https://norteaventura.com.ar/wp-content/uploads/2025/03/IMG-20240520-WA0124.jpg','Cuevas de Wayra, Tilcara, Jujuy, Argentina',32),
  ('inca-cueva-humahuaca','Inca Cueva','Humahuaca, Jujuy',(select id from public.categories where slug='jujuy'),'trekking',null,'Consultar precio','1 (un) día','Consultar horarios','Media','Pinturas rupestres y senderos poco conocidos de Humahuaca.','Excursión hacia el sitio Inca Cueva, con pinturas rupestres y evidencias arqueológicas únicas en la Quebrada de Humahuaca. Caminata interpretativa por un valle casi sin turismo masivo.','Guía, seguro.','Consultar disponibilidad.','https://norteaventura.com.ar/wp-content/uploads/2025/02/IMG-20250207-WA0023.jpg','Inca Cueva, Humahuaca, Jujuy, Argentina',33),
  ('laguna-de-pozuelo','Laguna de Pozuelo','Monumento Natural Laguna de los Pozuelos, Jujuy',(select id from public.categories where slug='jujuy'),'clasica',null,'Consultar precio','1 (un) día','Consultar horarios','Baja','Avistaje de aves en la laguna de altura más famosa del NOA.','Visita al Monumento Natural Laguna de los Pozuelos, refugio de flamencos y aves andinas a 3.700 msnm. Paisaje de puna infinita y observación de fauna en su hábitat natural.','Traslado, seguro, guiado.','Consultar disponibilidad.','https://norteaventura.com.ar/wp-content/uploads/2025/04/20220515_153224.jpg','Laguna de los Pozuelos, Jujuy, Argentina',34),
  ('cascadas-trekking-jujuy','Cascadas','Quebrada de Humahuaca, Jujuy',(select id from public.categories where slug='jujuy'),'trekking',null,'Consultar precio','1 (un) día','Consultar horarios','Media','Trekking entre cascadas escondidas de la quebrada.','Jornada de trekking entre cascadas y cauces de la Quebrada de Humahuaca: agua, piedra y vegetación sorprendente para quienes buscan lo verde detrás del paisaje árido.','Guía, seguro.','Consultar disponibilidad.','https://norteaventura.com.ar/wp-content/uploads/2025/03/20250105_115140.jpg','Quebrada de Humahuaca, Jujuy, Argentina',35),
  ('turismo-rural-jujuy','Turismo Rural','Tilcara, Jujuy',(select id from public.categories where slug='jujuy'),'trekking',null,'Consultar precio','1 (un) día','Consultar horarios','Baja','Experiencias con comunidades y productores del norte.','Experiencias de turismo rural junto a comunidades y productores de la Quebrada: agricultura andina, artesanías, comidas típicas y cultura viva en primera persona.','Guía local, actividades con la comunidad.','Consultar disponibilidad.','https://norteaventura.com.ar/wp-content/uploads/2025/03/IMG-20240503-WA0026.jpg','Tilcara, Jujuy, Argentina',36)
on conflict (slug) do nothing;

-- 5) Reservas: datos de pago (Mercado Pago)
alter table public.reservations
  add column if not exists payment_id text,
  add column if not exists payment_status text not null default 'unpaid',
  add column if not exists paid_at timestamptz;
